update_md5_c552a6a59cad00ea1c05bb8baaca6.content_md5_c552a6a59cad00ea1c05bb8baaca:
async function extractPdf(data: Buffer): Promise<string> {
  const parser = new PDFParse({ data });
  const result = await parser.getText();
  return result.text;
}
